parsed.sql:
WITH gaps AS (
  SELECT 
    b.DEESYNPUF_ID,
    MAX(
      DATEDIFF(
        CLM_DRG_CD_1, -- Using DRG code to identify the discharge date as it is not directly available in beneficiary table
        CLM_THRU_DT + INTERVAL '24 hours' -- Approximating discharge date from claim end date (though typically separate column exists)
      )
    ) AS gap_days
  FROM beneficiary b
  INNER JOIN inpatient_claims i ON b.DEESYNPUF_ID = i.DEESYNPUF_ID
  GROUP BY b.DEESYNPUF_ID
) SELECT MAX(gap_days) FROM gaps;

